import{_ as a,o as d,c as e,a2 as s}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"从这里开始","description":"","frontmatter":{"title":"从这里开始","order":1},"headers":[],"relativePath":"zh/learn/mod/index.md","filePath":"zh/learn/mod/index.md","lastUpdated":1786943111000}'),i={name:"zh/learn/mod/index.md"};function r(n,t,l,h,o,p){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h1><p>欢迎来到 ADOFAI Mod 开发教程。这个系列将引导你<strong>循序渐进</strong>地开发一个 <em>A Dance of Fire and Ice</em>（ADOFAI）的 Mod。</p><p>整个系列共 26 章，分为五个阶段：</p><table tabindex="0"><thead><tr><th>阶段</th><th>章节</th><th>你能得到什么</th></tr></thead><tbody><tr><td>☕ 前置</td><td>0</td><td>C# 基础速成（零基础补课）</td></tr><tr><td>🚀 入门</td><td>1~5</td><td>环境、UMM 原理、第一个 Mod、调试</td></tr><tr><td>🧩 Harmony</td><td>6~16</td><td>补丁全系列（含 Transpiler、Reverse Patch）</td></tr><tr><td>🛠️ 实战</td><td>17~19</td><td>设置界面、定位目标方法</td></tr><tr><td>🚢 进阶发布</td><td>20~25</td><td>多加载器、Mod API、CI/CD、规范</td></tr></tbody></table><p>在开始之前，希望你能具备以下基础知识：</p><ol><li><strong>没学过 C#？</strong> 先读<a href="./csharp-basics">《C# 基础速成》</a>，把第 0 章过一遍</li><li>有一定的 <strong>Git、GitHub</strong> 使用经验</li></ol><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><h3 id="_1-准备游戏" tabindex="-1">1. 准备游戏 <a class="header-anchor" href="#_1-准备游戏" aria-label="Permalink to &quot;1. 准备游戏&quot;">​</a></h3><ul><li>从 Steam 购买并安装 <em>A Dance of Fire and Ice</em></li><li>确保游戏可以正常启动</li></ul><h3 id="_2-安装-unitymodmanager" tabindex="-1">2. 安装 UnityModManager <a class="header-anchor" href="#_2-安装-unitymodmanager" aria-label="Permalink to &quot;2. 安装 UnityModManager&quot;">​</a></h3><ol><li>下载 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a>（0.27.0 或更高版本）</li><li>运行 UMM，在游戏列表中选择 ADOFAI</li><li>点击 <strong>Install</strong> 将 UMM 注入游戏</li></ol><h3 id="_3-安装开发工具" tabindex="-1">3. 安装开发工具 <a class="header-anchor" href="#_3-安装开发工具" aria-label="Permalink to &quot;3. 安装开发工具&quot;">​</a></h3><ul><li><strong>Visual Studio 2019+</strong> 或 <strong>JetBrains Rider</strong></li><li><strong>.NET Framework 4.8.1 Developer Pack</strong></li><li><strong>Harmony 2.3.3</strong></li></ul><h3 id="_4-获取官方模板" tabindex="-1">4. 获取官方模板 <a class="header-anchor" href="#_4-获取官方模板" aria-label="Permalink to &quot;4. 获取官方模板&quot;">​</a></h3><p>组织提供了两个 Mod 模板，本系列将使用第一个：</p><table tabindex="0"><thead><tr><th>模板</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/adofaiex/ADOFAIModTemplate" target="_blank" rel="noreferrer">ADOFAIModTemplate</a></td><td>基础模板，本系列的主角</td></tr><tr><td><a href="https://github.com/adofaiex/ADOFAIMod.MultiLoader" target="_blank" rel="noreferrer">ADOFAIMod.MultiLoader</a></td><td>多加载器进阶模板，见<a href="./multiloader">进阶章节</a></td></tr></tbody></table><p>克隆并安装基础模板：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/adofaiex/ADOFAIModTemplate.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADOFAIModTemplate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装为本地模板（从仓库目录）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOFAIModTemplate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或从 NuGet 包安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tArray.ADOFAIModTemplate.1.0.0.nupkg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_5-验证环境" tabindex="-1">5. 验证环境 <a class="header-anchor" href="#_5-验证环境" aria-label="Permalink to &quot;5. 验证环境&quot;">​</a></h3><p>用模板创建项目测试：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADOFAIModTemplate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MyFirstMod</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果生成了包含 <code>src/Main.cs</code>、<code>src/Settings.cs</code>、<code>src/Patches.cs</code> 的项目结构，说明环境就绪。</p><h2 id="调试你的-mod" tabindex="-1">调试你的 Mod <a class="header-anchor" href="#调试你的-mod" aria-label="Permalink to &quot;调试你的 Mod&quot;">​</a></h2><ul><li>UMM 采用运行时注入机制，调试时需要启动游戏本体</li><li>在 UMM 界面（默认 <code>Ctrl+F10</code>）中启用 / 禁用 Mod</li><li>观察游戏日志确认加载是否成功</li></ul><h2 id="开发原则" tabindex="-1">开发原则 <a class="header-anchor" href="#开发原则" aria-label="Permalink to &quot;开发原则&quot;">​</a></h2><p>感谢你为 ADOFAI 生态做出贡献，开发 Mod 请遵守以下原则：</p><ul><li>功能需经过测试</li><li>需包含良好的注释</li><li>持久化数据请存放于 Mod 的本地配置目录，防止更新时被覆盖</li><li>良好的错误处理机制，不要让 Mod 因一个错误而崩溃</li><li>如果是扩展现有 Mod 的功能，优先向原项目提交 PR</li></ul><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><p>完整章节列表如下，建议按顺序阅读：</p><table tabindex="0"><thead><tr><th>#</th><th>章节</th><th>内容</th></tr></thead><tbody><tr><td>0</td><td><a href="./csharp-basics">C# 基础速成</a></td><td>零基础补课（可选）</td></tr><tr><td>1</td><td><a href="./">从这里开始</a></td><td>环境准备、章节地图</td></tr><tr><td>2</td><td><a href="./what-is-mod">什么是 Mod</a></td><td>Mod 能做什么、开发红线</td></tr><tr><td>3</td><td><a href="./umm">认识 UMM</a></td><td>UMM 原理、Mod 目录、ModEntry</td></tr><tr><td>4</td><td><a href="./first-mod">最小实例</a></td><td>Info.json + Main.cs，第一个 Mod</td></tr><tr><td>5</td><td><a href="./build-debug">编译、部署与调试</a></td><td>编译、热重载、看日志</td></tr><tr><td>6</td><td><a href="./harmony">Harmony 入门</a></td><td>四种补丁类型总览</td></tr><tr><td>7</td><td><a href="./harmony-prefix">Prefix 补丁</a></td><td>拦截方法、修改参数</td></tr><tr><td>8</td><td><a href="./harmony-postfix">Postfix 补丁</a></td><td>修改返回值、<code>__state</code></td></tr><tr><td>9</td><td><a href="./harmony-finalizer">Finalizer 补丁</a></td><td>异常处理</td></tr><tr><td>10</td><td><a href="./harmony-magic-params">魔法参数详解</a></td><td><code>__instance</code> / <code>__result</code> / <code>__state</code></td></tr><tr><td>11</td><td><a href="./harmony-attributes">HarmonyPatch 详解</a></td><td>目标写法、优先级</td></tr><tr><td>12</td><td><a href="./harmony-lifecycle">补丁生命周期</a></td><td>PatchAll / 优先级</td></tr><tr><td>13</td><td><a href="./harmony-transpiler">Transpiler 入门</a></td><td>IL 是什么</td></tr><tr><td>14</td><td><a href="./harmony-transpiler-practice">Transpiler 实战</a></td><td>CodeMatcher</td></tr><tr><td>15</td><td><a href="./harmony-manual">手动补丁</a></td><td>动态打补丁</td></tr><tr><td>16</td><td><a href="./harmony-reverse">Reverse Patch</a></td><td>反向调用游戏方法</td></tr><tr><td>17</td><td><a href="./settings">设置系统</a></td><td>定义并持久化设置</td></tr><tr><td>18</td><td><a href="./settings-ui">绘制设置界面</a></td><td>IMGUI 界面</td></tr><tr><td>19</td><td><a href="./finding-methods">定位目标方法</a></td><td>dnSpy / ILSpy</td></tr><tr><td>20</td><td><a href="./multiloader">进阶：多加载器模板</a></td><td>UMM / Melon / BepInEx / Doorstop</td></tr><tr><td>21</td><td><a href="./sarcary">进阶：Mod API</a></td><td>Sarcary 公共 API</td></tr><tr><td>22</td><td><a href="./publish">打包与发布</a></td><td>Release 与发布</td></tr><tr><td>23</td><td><a href="./github-actions">GitHub Actions 自动构建</a></td><td>CI/CD、私有 lib 仓库</td></tr><tr><td>24</td><td><a href="./guidelines">模组开发规范</a></td><td>红线与质量要求</td></tr><tr><td>25</td><td><a href="./troubleshooting">常见问题与排查</a></td><td>FAQ</td></tr></tbody></table>`,30)])])}const m=a(i,[["render",r]]);export{k as __pageData,m as default};
